<?php
declare(strict_types=1);
namespace App\Application\Review\Service;
use App\Application\Review\DTO\Request\RateFlashcardRequestDto;use App\Application\Review\Port\TransactionManagerInterface;use App\Domain\Review\Entity\FlashcardReview;use App\Domain\Review\Repository\FlashcardReviewRepositoryInterface;use App\Domain\Review\Repository\ReviewSessionRepositoryInterface;use App\Domain\Review\Repository\UserFlashcardProgressRepositoryInterface;use App\Domain\Review\Service\SpacedRepetitionStrategyInterface;
final readonly class RateFlashcardService { public function __construct(private ReviewSessionRepositoryInterface $sessions,private UserFlashcardProgressRepositoryInterface $progresses,private FlashcardReviewRepositoryInterface $reviews,private SpacedRepetitionStrategyInterface $strategy,private TransactionManagerInterface $transactions){} public function execute(RateFlashcardRequestDto $request,\DateTimeImmutable $now):?FlashcardReview{return $this->transactions->transactional(function()use($request,$now):?FlashcardReview{$session=$this->sessions->findForUser($request->sessionId,$request->userId);if($session===null||!in_array($request->flashcardId,$session->flashcardIds,true))throw new \DomainException('Card de revisão não encontrado.');if($this->reviews->hasSessionReview($request->sessionId,$request->flashcardId))return null;$progress=$this->progresses->find($request->userId,$request->flashcardId);if($progress===null)throw new \DomainException('Progresso de revisão não encontrado.');$previous=$progress->state();$next=$this->strategy->next($previous,$request->rating,$now);$progress->apply($next,$now);$review=new FlashcardReview($this->uuid(),$request->userId,$request->flashcardId,$request->sessionId,$request->rating,$previous,$next,$now);$this->progresses->save($progress);$this->reviews->append($review);if(count($session->flashcardIds)===1)$session->complete($now);$this->sessions->save($session);return $review;});} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
